INSERT INTO `command_template` VALUES (2, 'for echo 0.05', 'for i in `seq 1 250`\ndo\n    sleep 0.05\n	echo $i\ndone', NULL, 1, 'orionadmin', 1, 'orionadmin', 1, '2026-03-20 19:35:35.0000', '2026-03-20 19:35:35.0000');
INSERT INTO `command_template` VALUES (3, 'for echo 1 c 10', 'for i in `seq 1 10`\ndo\n    sleep 1\n	echo $i\ndone', 'sleep 1 -c 10', 1, 'orionadmin', 1, 'orionadmin', 1, '2026-03-20 19:35:35.0000', '2026-03-20 19:35:35.0000');
INSERT INTO `command_template` VALUES (4, 'read value await', 'echo read\nread -p \"Enter value > \" value\necho \"value：$value\"', 'read await', 1, 'orionadmin', 1, 'orionadmin', 1, '2026-03-20 19:35:35.0000', '2026-03-20 19:35:35.0000');
INSERT INTO `command_template` VALUES (5, 'kill', 'PROGRESS=\nps -ef | grep $PROGRESS | grep -v grep | awk \'{print $2}\' | xargs kill -9 || echo $?', '通过进程名称执行kill命令', 1, 'orionadmin', 1, 'orionadmin', 1, '2026-03-20 19:35:35.0000', '2026-03-20 19:35:35.0000');
INSERT INTO `command_template` VALUES (6, '获取 pid', 'PROGRESS=\r\nPID=$(ps -ef | grep $PROGRESS | grep -v grep | awk \'{print $2}\')\r\nif [ ! -z $PID ]; then\r\n   echo \'pid: \' $PID\r\nfi', '获取进程 pid', 1, 'orionadmin', 1, 'orionadmin', 1, '2026-03-20 19:35:35.0000', '2026-03-20 19:35:35.0000');
INSERT INTO `command_template` VALUES (7, '删除文件', 'DEL_PATH=\r\nif [ -f \"$DEL_PATH\" ]; then\r\n rm -f $DEL_PATH\r\n echo \'删除文件\' $DEL_PATH\r\nfi', NULL, 1, 'orionadmin', 1, 'orionadmin', 1, '2026-03-20 19:35:35.0000', '2026-03-20 19:35:35.0000');
INSERT INTO `command_template` VALUES (8, '删除文件夹', 'DEL_PATH=\r\nif [ -d \"$DEL_PATH\" ]; then\r\n rm -rf $DEL_PATH\r\n echo \'删除文件夹\' $DEL_PATH\r\nfi', NULL, 1, 'orionadmin', 1, 'orionadmin', 1, '2026-03-20 19:35:35.0000', '2026-03-20 19:35:35.0000');
INSERT INTO `command_template` VALUES (9, '删除文件夹（window）', '@echo off\r\nset DEL_PATH=D:\r\nif exist \"%DEL_PATH%\" (\r\n    rmdir /s /q \"%DEL_PATH%\"\r\n    echo 删除文件夹 %DEL_PATH%\r\n) else (\r\n    echo 文件夹不存在: %DEL_PATH%\r\n)\r\npause', NULL, 1, 'orionadmin', 1, 'orionadmin', 1, '2026-03-22 20:41:25.4245', '2026-03-22 20:41:52.4310');
INSERT INTO `command_template` VALUES (10, '删除文件（window）', '@echo off\r\nset DEL_PATH=\r\nif exist \"%DEL_PATH%\" (\r\n    del /f /q \"%DEL_PATH%\"\r\n    echo 删除文件 %DEL_PATH%\r\n) else (\r\n    echo 文件不存在: %DEL_PATH%\r\n)\r\npause', NULL, 1, 'orionadmin', 1, 'orionadmin', 1, '2026-03-22 20:42:12.8256', '2026-03-22 20:42:12.8256');
INSERT INTO `command_template` VALUES (11, '获取pid(window)', '@echo off\r\nset PROGRESS=\r\nfor /f \"tokens=2\" %%i in (\'tasklist /fi \"imagename eq %PROGRESS%.exe\" /nh 2^>nul\') do set PID=%%i\r\nif not \"%PID%\"==\"\" (\r\n    echo pid: %PID%\r\n) else (\r\n    echo 进程不存在: %PROGRESS%\r\n)\r\npause', NULL, 1, 'orionadmin', 1, 'orionadmin', 1, '2026-03-22 20:43:00.6297', '2026-03-22 20:43:27.6810');
INSERT INTO `command_template` VALUES (12, 'kill(window)', '@echo off\r\nset PROGRESS=\r\ntaskkill /f /im %PROGRESS%.exe 2>nul\r\nif %errorlevel% equ 0 (\r\n    echo 已终止进程: %PROGRESS%\r\n) else (\r\n    echo 进程不存在或无法终止: %PROGRESS%\r\n    echo 错误码: %errorlevel%\r\n)\r\npause', NULL, 1, 'orionadmin', 1, 'orionadmin', 1, '2026-03-22 20:43:46.4092', '2026-03-22 20:43:46.4092');
INSERT INTO `command_template` VALUES (13, 'read value await(window)', '@echo off\r\necho 请输入值:\r\nset /p value=\r\necho value：%value%\r\npause', NULL, 1, 'orionadmin', 1, 'orionadmin', 1, '2026-03-22 20:44:35.6648', '2026-03-22 20:44:35.6648');
